    # --- writes --------------------------------------------------------------------------------------

    def run(fn: Any, *args: Any) -> Any:
        try:
            return fn(*args)
        except ValidationError as e:
            raise HTTPException(422, [err["msg"] for err in e.errors()]) from None
        except NotFound:
            raise HTTPException(404, "not found") from None
        except Invalid as e:
            raise HTTPException(422, str(e)) from None

    @app.post("/api/shots")
    def post_shot(body: dict, me: OutboxWriter) -> dict:
        shot, written = run(store.save_shot, me.user_id, body)
        return {"shot_id": shot.shot_id, "written": written}

    @app.post("/api/shots/{shot_id}/retract")
    def retract(shot_id: str, me: OutboxWriter) -> dict:
        return {"shot_id": shot_id, "written": run(store.retract_shot, me.user_id, shot_id)}

    @app.post("/api/shots/{shot_id}/restore")
    def restore(shot_id: str, me: OutboxWriter) -> dict:
        return {"shot_id": shot_id, "written": run(store.restore_shot, me.user_id, shot_id)}

    @app.post("/api/equipment")
    def post_equipment(body: dict, me: OutboxWriter) -> dict:
        return {"equipment_id": run(store.save_equipment, me.user_id, body).equipment_id}

    photo_lake = photos_lake or Lake.photos()
    reads_today: dict[
        tuple[str, str], int
    ] = {}  # (user, date) -> label reads; in memory, so a restart resets it
    # photo_id -> (user, matched coffee_id, score, raw read, roast date): in memory, for the offline hand-off
    photo_reads: dict[str, tuple[str, str | None, int | None, str | None, str | None]] = {}
    last_reply: dict[str, tuple[str, dict]] = {}  # photo_id -> (owner, reply): a resend isn't read twice
    # One upload of a photo at a time: two copies in flight together (the outbox resending one still on its way)
    # would both miss last_reply and pay for two reads. The second waits, then gets the first's reply. A photo's
    # lock goes once no upload of it is in flight, whichever way the last one ended (reply, limit, 409, error).
    reading: dict[str, tuple[asyncio.Lock, int]] = {}  # photo_id -> (lock, uploads holding or waiting on it)
    app.state.photo_locks = reading

    @contextlib.asynccontextmanager
    async def one_at_a_time(photo_id: str) -> AsyncIterator[None]:
        lock, n = reading.get(photo_id) or (asyncio.Lock(), 0)
        reading[photo_id] = (lock, n + 1)
        try:
            async with lock:
                yield
        finally:
            lock, n = reading[photo_id]
            if n == 1:
                del reading[photo_id]
            else:
                reading[photo_id] = (lock, n - 1)

    def describe(coffee_id: str | None) -> dict | None:
        c = store.coffee(coffee_id)
        if not c:
            return None
        notes = c.get("tasting_notes")
        # "Ethiopia, washed": the process rides along with a place, never stands in for one (a catalog row with no
        # country showed "Origin: honey").
        place = [x for x in (c.get("origin_country"), c.get("origin_region")) if x]
        return {
            "coffee_id": coffee_id,
            "title": c.get("title"),
            "roaster": " · ".join(x for x in (c.get("roaster_name"), c.get("roaster_state")) if x),
            "origin": ", ".join(place + [c["process"]] if place and c.get("process") else place),
            "past": c.get("catalog_status") == "archived",  # no longer listed by the roaster
            "notes": ", ".join(str(n) for n in notes) if notes is not None and len(notes) else None,
            "price": f"${c['price_per_100g']:.2f} / 100 g" if c.get("price_per_100g") else None,
            "in_stock": c.get("in_stock"),
        }

    @app.get("/api/coffees/search")
    def search_coffees(me: Me, q: str = Query("", max_length=120)) -> dict:
        """Offer catalog candidates for an explicit choice; never silently change a bag's match."""
        query = q.strip()
        if len(query) < 2:
            return {"coffees": []}
        unavailable = "The catalog isn’t available right now. Try again shortly."
        try:
            candidates = shots.search_catalog(query, limit=12, lake=lake)
        except RuntimeError:
            raise HTTPException(503, unavailable) from None
        coffees = [describe(m["coffee_id"]) for m in candidates]
        if None in coffees:  # in the catalog's index, but its facts couldn't be read
            raise HTTPException(503, unavailable)
        return {"coffees": coffees}

    @app.post("/api/photos/{photo_id}")
    async def post_photo(photo_id: str, request: Request, me: OutboxWriter) -> dict:
        """A bag photo: checked, re-encoded without metadata, saved, then read by Claude and matched in Python.
        Reading needs ANTHROPIC_API_KEY and is capped per account per day; without either, the person types it."""
        if not SAFE_ID.fullmatch(photo_id):
            raise HTTPException(422, "bad photo id")
        if request.headers.get("content-type", "").split(";")[0] not in (
            "image/jpeg",
            "image/png",
            "image/webp",
        ):
            raise HTTPException(415, "Send the photo as JPEG, PNG or WebP.")
        try:
            # Decoding, resizing and encoding take a moment of CPU: off the event loop, like the save and the read.
            photo = await run_in_threadpool(photos.normalize, await request.body())
        except photos.BadPhoto as e:
            raise HTTPException(422, str(e)) from None
        async with one_at_a_time(photo_id):
            if photo_id in last_reply:  # a resend from the outbox: the same reply, without a second read
                owner, reply = last_reply[photo_id]
                if owner != me.user_id:
                    raise HTTPException(409, "That photo id is taken.")
                return reply
            key = (me.user_id, datetime.now(UTC).date().isoformat())
            if reads_today.get(key, 0) >= READS_PER_DAY:
                # Past the day's reads the photo isn't kept either, so uploads can't fill the dataset.
                return {"photo_id": None, "status": "limit", "label": None, "raw": None}
            reads_today[key] = reads_today.get(key, 0) + 1
            # The dataset commit (which can retry for a while) and the label read run side by side.
            saved, result = await asyncio.gather(
                run_in_threadpool(photos.save, photo_lake, photo_id, me.user_id, photo),
                run_in_threadpool(labels.read, photo.jpeg, None, labels_client),
            )
            if (
                saved is False
                and (await run_in_threadpool(photos.load, photo_lake, photo_id) or ("",))[0] != me.user_id
            ):
                raise HTTPException(409, "That photo id is taken.")  # someone else's, from before a restart
            photo_misses.pop(photo_id, None)
            out: dict[str, Any] = {
                "photo_id": photo_id,
                "status": result.status,
                "label": result.label,
                "raw": result.raw,
            }
            if result.status == "read" and result.label:
                out |= await run_in_threadpool(matched, result)
                # Kept so a bag that cites this photo can use the read, whichever of the two reaches the server first
                # (offline, the photo and the bag wait in the outbox together).
                coffee_id = (out["match"] or {}).get("coffee_id")
                photo_reads[photo_id] = (me.user_id, coffee_id, out["score"], result.raw, out["roast_date"])
                await run_in_threadpool(apply_read, me.user_id, photo_id)
            last_reply[photo_id] = (me.user_id, out)
            return out

    def apply_read(user_id: str, photo_id: str) -> None:
        """A bag saved before its photo was read (typed while offline) takes the read's match, if there was one
        and the typed text matched nothing."""
        hit = photo_reads.get(photo_id)
        if not hit or hit[0] != user_id or not hit[1]:
            return
        for bag in store.bags_of(user_id):
            if bag.photo_id == photo_id and not bag.coffee_id:
                update = {"coffee_id": hit[1], "match_score": hit[2], "read_json": bag.read_json or hit[3]}
                if not bag.roast_date and hit[4]:
                    update["roast_date"] = hit[4]
                store.save_bag(user_id, bag.model_dump(exclude={"user_id"}) | update)

    def matched(result: labels.Read) -> dict[str, Any]:
        """The catalog match for a read label, described for the screen."""
        label = result.label or {}
        coffee_id, candidates = shots.match_bag(label.get("roaster"), label.get("coffee"), lake)
        described = [(describe(m["coffee_id"]), m["score"]) for m in candidates]  # ties: sold now first
        roast = result.roast_date()
        return {
            "match": describe(coffee_id),
            "score": candidates[0]["score"] if coffee_id and candidates else None,
            "candidates": [d | {"score": score} for d, score in described if d],
            "roast_date": roast.isoformat() if roast else None,
        }

    @app.post("/api/bags")
    def post_bag(body: dict, me: OutboxWriter) -> dict:
        # Only a bag typed before its photo was read (offline) takes the photo's match. A bag typed after seeing the
        # read chose not to use it, and keeps what was typed (#20-1).
        pending = bool(body.pop("read_pending", False))
        bag, matches = run(store.save_bag, me.user_id, body)
        if pending and bag.photo_id and not bag.coffee_id:
            apply_read(me.user_id, bag.photo_id)  # the photo got here first and was read
            bag = store.bag(me.user_id, bag.bag_id) or bag
        return {"bag_id": bag.bag_id, "coffee_id": bag.coffee_id, "matches": matches}

    return app


def __getattr__(name: str) -> FastAPI:
    # `uvicorn app.main:app` builds the app on first use, so importing this module (tests) has no side effects.
    if name == "app":
        if logs.wanted():
            logs.setup()
        globals()["app"] = a = create_app()
        return a
    raise AttributeError(name)

{% extends "base.html" %}
{% from "_macros.html" import nav, shotrow %}
{% block title %}{{ name }} · registry.coffee{% endblock %}
{% block main %}
  <div class="top"><a class="back" href="/coffees">‹ Coffees</a>
    {% if siblings | length > 1 %}<span class="meta">Bag {{ index }} of {{ siblings | length }}{% if index > 1 %} <a class="ext tap" href="/coffee/{{ siblings[index - 2].bag_id }}">‹ earlier</a>{% endif %}{% if index < siblings | length %} <a class="ext tap" href="/coffee/{{ siblings[index].bag_id }}">later ›</a>{% endif %}</span>{% endif %}</div>
  {% if bag.photo_id %}<img class="cover mt8" src="/photos/{{ bag.photo_id }}" alt="The bag" width="358" height="179" fetchpriority="high">{% endif %}
  <h1 class="serif title mt16">{{ name }}</h1>
  <div class="body">{{ facts }}</div>
  <div class="row"><span class="meta">
    {%- if bag.roast_date %}Roasted {{ bag.roast_date.strftime("%b ") ~ bag.roast_date.day }} · day {{ days_off }}{% endif %}
    {%- if bag.roast_date and bag.finished_on %} · {% endif %}
    {%- if bag.finished_on %}{{ "finished" if bag.roast_date else "Finished" }} {{ bag.finished_on.strftime("%b ") ~ bag.finished_on.day }}{% endif -%}
  </span><a class="ext tap" href="/bag/{{ bag.bag_id }}/edit">Edit bag</a></div>

  {% if best %}
  {% set gr = grinder_of(best) %}
  <h2 class="section">Best so far · rated {{ best.rating }}, {{ date(best.brewed_at) }}{% if gr %} · {{ gr.name }}{% endif %}</h2>
  <div class="best">
    <div><span class="label">Dose</span><span class="num n34">{{ g(best.dose_g, 1) }}<span class="u"> g</span></span></div>
    <div><span class="label">Yield</span><span class="num n34">{{ g(best.yield_g, 1) }}<span class="u"> g</span></span></div>
    <div><span class="label">Time</span><span class="num n34">{{ g(best.time_s) }}<span class="u"> s</span></span></div>
    <div><span class="label">Grind</span><span class="num n34">{{ g(best.grinder_setting) }}</span></div>
  </div>
  <h2 class="section">All {{ shots_n(n_all) }}</h2>
  <div>{{ chart | safe }}</div>
  <div class="legend mt8" aria-hidden="true">{% for t, l in (("sour", "Sour"), ("balanced", "Balanced"), ("bitter", "Bitter"), ("none", "No taste")) if t in tastes %}<span class="key {{ t }}">{{ l }}</span>{% endfor %}</div>
  {% else %}
  <p class="body mt24 ruled">No shots of this coffee yet.</p>
  {% endif %}

  {% if shots %}
  <h2 class="section">This bag</h2>
  <div class="list">{% for s in shots[:5] %}{{ shotrow(s, day) }}{% endfor %}</div>
  {% if shots | length > 5 %}
  <details class="disclose"><summary class="btn text start">All {{ shots_n(shots | length) }}</summary>
    <div class="list">{% for s in shots[5:] %}{{ shotrow(s, day) }}{% endfor %}</div>
  </details>
  {% endif %}
  {% endif %}

  {% if catalog %}
  <h2 class="section">From the catalog</h2>
  <dl class="spec">
    {% if catalog.origin %}<dt>Origin</dt><dd>{{ catalog.origin }}</dd>{% endif %}
    {% if raw.elevation_masl_min %}<dt>Elevation</dt><dd>{{ "{:,}".format(raw.elevation_masl_min | int) }}{% if raw.elevation_masl_max and raw.elevation_masl_max != raw.elevation_masl_min %}–{{ "{:,}".format(raw.elevation_masl_max | int) }}{% endif %} m</dd>{% endif %}
    {% if catalog.notes %}<dt>Notes</dt><dd>{{ catalog.notes }}</dd>{% endif %}
    {% if catalog.price %}<dt>Price</dt><dd>{{ catalog.price }}</dd>{% endif %}
    {% if catalog.in_stock is not none %}<dt>Stock</dt><dd>{{ "In stock" if catalog.in_stock else "Sold out" }}</dd>{% endif %}
    {% if raw.url and raw.url.startswith(("https://", "http://")) %}<dt>Shop</dt><dd><a class="ext" href="{{ raw.url }}" rel="noopener noreferrer" target="_blank">{{ raw.url.split("/")[2] }}</a></dd>{% endif %}
  </dl>
  {% endif %}
  <div class="mt24"></div>
{% endblock %}
{% block nav %}{{ nav('coffees') }}{% endblock %}

