  // stops the queue, so nothing passes an earlier write that hasn't landed.
  const entries = (await mine()).filter((e) => !e.failed).sort((a, b) => a.at - b.at);
  for (const entry of entries) {
    try {
      await deliver(entry);
      backoff = 0;
    } catch (e) {
      if (!(e instanceof Rejected)) {
        later(e.wait);
